    private static Path root(){return Minecraft.getInstance().gameDirectory.toPath();}
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static Object field(Object object,String name)throws Exception{for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{var f=c.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    private static Object readUnchecked(Object object,String name){try{return field(object,name);}catch(Exception e){throw new IllegalStateException(e);}}
    private static Object call(Object object,String name,Class<?>[] types,Object...args)throws Exception{var m=object.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(object,args);}
    private static EditorRuntime.Loaded loaded(String id){return EditorRuntime.recipes().stream().filter(r->r.id().equals(id)).findFirst().orElseThrow(()->new AssertionError("Missing "+id));}
    private static void click(String text){var screen=Minecraft.getInstance().screen;var b=screen.children().stream().filter(c->c instanceof Button button&&button.getMessage().getString().contains(text)).map(c->(Button)c).findFirst().orElseThrow(()->new AssertionError("Missing button "+text+" on "+screen.getClass()));check(b.active,"Button enabled "+text);check(screen.mouseClicked(b.getX()+2,b.getY()+2,0),"Actual mouse click "+text);screen.mouseReleased(b.getX()+2,b.getY()+2,0);}
