        var mc=Minecraft.getInstance();mc.options.guiScale().set(scale);mc.resizeDisplay();open(id);var screen=(CompatibilityScreen)mc.screen;var p=(RecipePresentation)field(screen,"presentation");var regions=(Map<?,?>)field(screen,"regions");var row=new JsonObject();row.addProperty("id",id);row.addProperty("scale",scale);row.addProperty("source",p.definition.source);row.addProperty("ghosts",screen.ghostTargets().size());row.add("bindings",ProjectStore.JSON.toJsonTree(regions));actions.add(row);check(p!=null,"Presentation exists "+id);check(!screen.ghostTargets().isEmpty(),"Direct JEI targets without manual mapping "+id+" "+regions);
        if(id.startsWith("actuallyadditions")||id.startsWith("powah"))check(p.definition.source.equals("legacy-simple"),"Legacy adapter delegates original format "+id);
        var panel=(List<?>)call(screen,"panelBindings",new Class[]{});if(p.bindings().stream().anyMatch(b->!b.field().slot()))check(panel.stream().map(v->(RecipePresentation.Binding)v).allMatch(b->!b.field().slot()),"Parameters visible before materials "+id);
        var chosen=p.bindings().stream().filter(b->b.field().slot()&&!b.output()&&!b.fluid()&&b.field().registry.isBlank()&&regions.containsKey(b.key())).findFirst().orElseThrow();var rect=(net.minecraft.client.renderer.Rect2i)regions.get(chosen.key());var area=(net.minecraft.client.renderer.Rect2i)call(screen,"screenRect",new Class[]{net.minecraft.client.renderer.Rect2i.class},rect);check(area!=null,"Scaled target visible "+id);
